# Generated by build.py from recipe.yml for recipe imap-file-mail-into-a-folder. Do not edit.
set -e
cd "$(dirname "$0")"
surl --mail-domain example.com --mailbox ann@example.com:annpass --mailbox shop@example.com:shoppass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[1-3].eml" smtp://127.0.0.1:8080/example.com
curl -sS -o /dev/null --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:annpass -X "FETCH 3 FLAGS" imap://127.0.0.1:8081/INBOX
curl -s -u ann@example.com:annpass -X "CREATE Archive" imap://127.0.0.1:8081/ --next -s -u ann@example.com:annpass -X "COPY 1 Archive" imap://127.0.0.1:8081/INBOX --next -s -u ann@example.com:annpass -X "STORE 1 +FLAGS (\Deleted)" imap://127.0.0.1:8081/INBOX --next -s -u ann@example.com:annpass -X "EXPUNGE" imap://127.0.0.1:8081/INBOX --next -s -u ann@example.com:annpass -X "STATUS INBOX (MESSAGES)" imap://127.0.0.1:8081/ --next -s -u ann@example.com:annpass -X "STATUS Archive (MESSAGES)" imap://127.0.0.1:8081/
kill $(jobs -p)
